
create extension if not exists pgcrypto;
create schema if not exists private;
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null,slug text unique,document text,phone text,email text,timezone text not null default 'America/Campo_Grande',currency text not null default 'BRL',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',phone text,avatar_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.org_memberships(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'owner' check(role in ('owner','admin','manager','professional','receptionist','finance','viewer')),status text not null default 'active' check(status in ('active','invited','suspended')),created_at timestamptz not null default now(),unique(org_id,user_id));
create table public.branches(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,name text not null,phone text,email text,document text,address jsonb not null default '{}'::jsonb,is_main boolean not null default false,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(org_id,id));
create table public.customers(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,branch_id uuid,name text not null,phone text,email text,birth_date date,notes text,tags text[] not null default '{}',active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(org_id,branch_id) references public.branches(org_id,id),unique(org_id,id));
create table public.professionals(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,branch_id uuid,profile_id uuid references public.profiles(id) on delete set null,name text not null,phone text,email text,color text not null default '#B99A62',commission_rate numeric(6,3) not null default 0 check(commission_rate between 0 and 100),active boolean not null default true,schedule jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(org_id,branch_id) references public.branches(org_id,id),unique(org_id,id));
create table public.services(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,name text not null,description text,duration_minutes integer not null default 30 check(duration_minutes>0),price numeric(12,2) not null default 0 check(price>=0),category text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(org_id,id));
create table public.products(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,branch_id uuid,name text not null,sku text,barcode text,description text,category text,cost_price numeric(12,2) not null default 0 check(cost_price>=0),sale_price numeric(12,2) not null default 0 check(sale_price>=0),stock_quantity numeric(12,3) not null default 0,min_stock numeric(12,3) not null default 0,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(org_id,branch_id) references public.branches(org_id,id),unique(org_id,sku),unique(org_id,id));
create table public.inventory_movements(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,branch_id uuid,product_id uuid not null,movement_type text not null check(movement_type in ('in','out','adjustment')),quantity numeric(12,3) not null check(quantity>0),unit_cost numeric(12,2),reason text,reference_id uuid,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),foreign key(org_id,branch_id) references public.branches(org_id,id),foreign key(org_id,product_id) references public.products(org_id,id));
create table public.appointments(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,branch_id uuid,customer_id uuid,professional_id uuid,service_id uuid,customer_name text not null,customer_phone text,service_name text not null,professional_name text,starts_at timestamptz not null,ends_at timestamptz not null,status text not null default 'scheduled' check(status in ('scheduled','confirmed','arrived','in_progress','completed','cancelled','no_show')),price numeric(12,2) not null default 0,notes text,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at>starts_at),foreign key(org_id,branch_id) references public.branches(org_id,id),foreign key(org_id,customer_id) references public.customers(org_id,id),foreign key(org_id,professional_id) references public.professionals(org_id,id),foreign key(org_id,service_id) references public.services(org_id,id),unique(org_id,id));
create index appointments_org_starts_idx on public.appointments(org_id,starts_at);
create index appointments_professional_starts_idx on public.appointments(org_id,professional_id,starts_at);
create table public.appointment_blocks(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,branch_id uuid,professional_id uuid,starts_at timestamptz not null,ends_at timestamptz not null,reason text not null,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),check(ends_at>starts_at),foreign key(org_id,branch_id) references public.branches(org_id,id),foreign key(org_id,professional_id) references public.professionals(org_id,id));
create table public.sales(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,branch_id uuid,customer_id uuid,appointment_id uuid,sale_number bigint generated by default as identity,status text not null default 'open' check(status in ('open','paid','cancelled','refunded')),subtotal numeric(12,2) not null default 0,discount numeric(12,2) not null default 0,total numeric(12,2) not null default 0,payment_method text,notes text,sold_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),foreign key(org_id,branch_id) references public.branches(org_id,id),foreign key(org_id,customer_id) references public.customers(org_id,id),foreign key(org_id,appointment_id) references public.appointments(org_id,id),unique(org_id,id));
create table public.sale_items(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,sale_id uuid not null,product_id uuid,service_id uuid,description text not null,quantity numeric(12,3) not null default 1 check(quantity>0),unit_price numeric(12,2) not null default 0,discount numeric(12,2) not null default 0,total numeric(12,2) not null default 0,created_at timestamptz not null default now(),foreign key(org_id,sale_id) references public.sales(org_id,id) on delete cascade,foreign key(org_id,product_id) references public.products(org_id,id),foreign key(org_id,service_id) references public.services(org_id,id));
create table public.cash_registers(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,branch_id uuid,opened_by uuid references auth.users(id) on delete set null,closed_by uuid references auth.users(id) on delete set null,opening_amount numeric(12,2) not null default 0,closing_amount numeric(12,2),expected_amount numeric(12,2),status text not null default 'open' check(status in ('open','closed')),opened_at timestamptz not null default now(),closed_at timestamptz,notes text,foreign key(org_id,branch_id) references public.branches(org_id,id),unique(org_id,id));
create table public.cash_movements(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,branch_id uuid,cash_register_id uuid,sale_id uuid,movement_type text not null check(movement_type in ('income','expense')),category text,description text not null,amount numeric(12,2) not null check(amount>0),payment_method text,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),foreign key(org_id,branch_id) references public.branches(org_id,id),foreign key(org_id,cash_register_id) references public.cash_registers(org_id,id),foreign key(org_id,sale_id) references public.sales(org_id,id));
create table public.expenses(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,branch_id uuid,description text not null,category text,amount numeric(12,2) not null check(amount>0),due_date date,paid_at timestamptz,status text not null default 'pending' check(status in ('pending','paid','cancelled')),supplier text,notes text,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(org_id,branch_id) references public.branches(org_id,id));
create table public.commission_rules(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,professional_id uuid,service_id uuid,rate numeric(6,3) not null check(rate between 0 and 100),active boolean not null default true,created_at timestamptz not null default now(),foreign key(org_id,professional_id) references public.professionals(org_id,id),foreign key(org_id,service_id) references public.services(org_id,id));
create table public.commissions(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,professional_id uuid not null,sale_id uuid,appointment_id uuid,base_amount numeric(12,2) not null default 0,rate numeric(6,3) not null default 0,amount numeric(12,2) not null default 0,status text not null default 'pending' check(status in ('pending','approved','paid','cancelled')),paid_at timestamptz,created_at timestamptz not null default now(),foreign key(org_id,professional_id) references public.professionals(org_id,id),foreign key(org_id,sale_id) references public.sales(org_id,id),foreign key(org_id,appointment_id) references public.appointments(org_id,id));
create table public.app_settings(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,branch_id uuid,setting_key text not null,setting_value jsonb not null default '{}'::jsonb,updated_by uuid references auth.users(id) on delete set null,updated_at timestamptz not null default now(),foreign key(org_id,branch_id) references public.branches(org_id,id),unique(org_id,branch_id,setting_key));
create table public.notifications(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,title text not null,body text,kind text not null default 'info',read_at timestamptz,created_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id) on delete cascade,actor_id uuid references auth.users(id) on delete set null,action text not null,entity_type text not null,entity_id uuid,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create or replace function private.is_org_member(target_org uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.org_memberships m where m.org_id=target_org and m.user_id=(select auth.uid()) and m.status='active'); $$;
create or replace function private.is_org_admin(target_org uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.org_memberships m where m.org_id=target_org and m.user_id=(select auth.uid()) and m.status='active' and m.role in ('owner','admin','manager')); $$;
revoke all on function private.is_org_member(uuid),private.is_org_admin(uuid) from public,anon;
grant usage on schema private to authenticated;
grant execute on function private.is_org_member(uuid),private.is_org_admin(uuid) to authenticated;
create or replace function private.bootstrap_new_user() returns trigger language plpgsql security definer set search_path='' as $$
declare new_org uuid; org_name text; full_name text;
begin
 full_name:=coalesce(nullif(trim(new.raw_user_meta_data->>'full_name'),''),split_part(coalesce(new.email,''),'@',1));
 org_name:=coalesce(nullif(trim(new.raw_user_meta_data->>'organization_name'),''),'Meu Salão');
 insert into public.organizations(name) values(org_name) returning id into new_org;
 insert into public.profiles(id,full_name) values(new.id,full_name);
 insert into public.org_memberships(org_id,user_id,role,status) values(new_org,new.id,'owner','active');
 insert into public.branches(org_id,name,is_main) values(new_org,'Unidade Matriz',true);
 return new;
end $$;
revoke all on function private.bootstrap_new_user() from public,anon,authenticated;
create trigger on_auth_user_created_salao after insert on auth.users for each row execute function private.bootstrap_new_user();
do $$ declare t text; begin
 foreach t in array array['branches','customers','professionals','services','products','inventory_movements','appointments','appointment_blocks','sales','sale_items','cash_registers','cash_movements','expenses','commission_rules','commissions','app_settings','notifications','audit_logs'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('grant select,insert,update,delete on public.%I to authenticated',t);
 execute format('create policy %I on public.%I for select to authenticated using(private.is_org_member(org_id))',t||'_select_member',t);
 execute format('create policy %I on public.%I for insert to authenticated with check(private.is_org_admin(org_id))',t||'_insert_admin',t);
 execute format('create policy %I on public.%I for update to authenticated using(private.is_org_admin(org_id)) with check(private.is_org_admin(org_id))',t||'_update_admin',t);
 execute format('create policy %I on public.%I for delete to authenticated using(private.is_org_admin(org_id))',t||'_delete_admin',t);
 end loop; end $$;
alter table public.organizations enable row level security;
grant select,update on public.organizations to authenticated;
create policy organizations_select_member on public.organizations for select to authenticated using(private.is_org_member(id));
create policy organizations_update_admin on public.organizations for update to authenticated using(private.is_org_admin(id)) with check(private.is_org_admin(id));
alter table public.org_memberships enable row level security;
grant select on public.org_memberships to authenticated;
create policy memberships_select_self_or_admin on public.org_memberships for select to authenticated using(user_id=(select auth.uid()) or private.is_org_admin(org_id));
alter table public.profiles enable row level security;
grant select,insert,update on public.profiles to authenticated;
create policy profiles_select_self on public.profiles for select to authenticated using(id=(select auth.uid()));
create policy profiles_update_self on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
grant usage,select on all sequences in schema public to authenticated;
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); return new; end $$;
revoke all on function public.set_updated_at() from public,anon,authenticated;
do $$ declare t text; begin foreach t in array array['organizations','profiles','branches','customers','professionals','services','products','appointments','expenses'] loop execute format('create trigger %I before update on public.%I for each row execute function public.set_updated_at()',t||'_set_updated_at',t); end loop; end $$;
